// GTK mnemonic suffixes are not keyboard shortcuts in CanopyOS.
for (const language of ['ja', 'ko', 'zh-CN', 'zh-TW', 'zh-HK']) {
  const catalog = window.CANOPY_DESKTOP_TRANSLATIONS[language] || {};
  for (const key of Object.keys(catalog)) catalog[key] = catalog[key].replace(/\s*[（(][A-Za-z][)）]\s*$/, '');
}

