for (const [locale, values] of Object.entries(CANOPY_CUSTOM_TEXT)) Object.assign(window.CANOPY_DESKTOP_TRANSLATIONS[locale], values);
// The remaining supported languages can at least use their translated Start/Stop labels.
for (const catalog of Object.values(window.CANOPY_DESKTOP_TRANSLATIONS)) {
  if (!catalog['Start Fern Live'] && catalog.Start) catalog['Start Fern Live'] = catalog.Start + ' Fern Live';
  if (!catalog['Stop Fern Live'] && catalog.Stop) catalog['Stop Fern Live'] = catalog.Stop + ' Fern Live';
}
